// Premium Vedic Astrology Planet Interpretation Engine
// Part of the Divine Compass Detailed Kundali Report System

export interface PlanetInterpretation {
  planet: string;
  sign: string;
  houseNumber: number;
  dignity: string; // 'exalted' | 'own' | 'friendly' | 'neutral' | 'debilitated' | 'enemy'
  signMeaning: string;
  houseInterpretation: string;
  strengths: string;
  challenges: string;
  lifeImpact: string;
  keyAreas: string[];
}

export interface PlanetInputs {
  sunLon: number;
  moonLon: number;
  marsLon: number;
  mercuryLon: number;
  jupiterLon: number;
  venusLon: number;
  saturnLon: number;
  rahuLon: number;
  ketuLon: number;
  lagnaIndex: number;
}

